/**
 * CloudStream 3 Provider for CineStream (https://cinestream.studio)
 * Generated by CloudStream CineStream Plugin Studio
 * Version: 1.0.0 (1)
 */
class CinestreamProvider : MainAPI() {
    override var mainUrl = "https://cinestream.studio"
    override var name = "CineStream"
    override val supportedTypes = setOf(TvType.Movie, TvType.TvSeries)
    override var lang = "es"
    override val hasMainPage = true
    override val hasQuickSearch = true

    companion object {
        private const val TMDB_IMAGE_BASE = "https://image.tmdb.org/t/p/w500"
        private const val TMDB_BACKDROP_BASE = "https://image.tmdb.org/t/p/w1280"

        // Streaming Servers Base URLs
        private const val VIDEASY_BASE = "https://player.videasy.to"
        private const val VIDY_BASE = "https://www.vidy.st"
        private const val VIDBOLT_BASE = "https://vidbolt.xyz"
        private const val FILMU_BASE = "https://embed.filmu.in"
        private const val VIDFAST_BASE = "https://vidfast.vc"
        private const val MAPPLE_BASE = "https://mapple.fun/embed"
        private const val SCREENSCAPE_BASE = "https://screenscape.me/embed"
        private const val VIDSRC_BASE = "https://vidsrc.pm/embed"
    }

    // ─────────────────────────────────────────────
    // MAIN PAGE SECTIONS
    // ─────────────────────────────────────────────
    override val mainPage = mainPageOf(
        "$mainUrl/api/trending/all/week" to "Trending Now",
        "$mainUrl/api/movie/popular" to "Popular Movies",
        "$mainUrl/api/tv/popular" to "Popular TV Shows",
        "$mainUrl/api/movie/top_rated" to "Top Rated Movies",
        "$mainUrl/api/tv/top_rated" to "Top Rated Series",
        "$mainUrl/api/movie/now_playing" to "Now Playing in Theaters"
    )

    override suspend fun getMainPage(
        page: Int,
        request: MainPageRequest
    ): HomePageResponse {
        val url = "${request.data}?page=$page"
        val response = app.get(
            url,
            headers = mapOf(
                "User-Agent" to "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Referer" to "$mainUrl/"
            )
        ).text

        val json = tryParseJson<TmdbListResponse>(response)
        val homeItems = json?.results?.mapNotNull { item ->
            item.toSearchResponse(mainUrl)
        } ?: emptyList()

        return newHomePageResponse(
            list = HomePageList(
                name = request.name,
                list = homeItems,
                isHorizontalImages = false
            ),
            hasNext = (json?.page ?: 1) < (json?.totalPages ?: 1)
        )
    }

    // ─────────────────────────────────────────────
    // SEARCH
    // ─────────────────────────────────────────────
    override suspend fun search(query: String): List<SearchResponse> {
        val url = "$mainUrl/api/search?q=${encodeUrl(query)}&page=1"
        val response = app.get(
            url,
            headers = mapOf(
                "User-Agent" to "Mozilla/5.0",
                "Referer" to "$mainUrl/"
            )
        ).text

        val json = tryParseJson<TmdbListResponse>(response) ?: return emptyList()
        return json.results.mapNotNull { item ->
            item.toSearchResponse(mainUrl)
        }
    }

    override suspend fun quickSearch(query: String): List<SearchResponse> = search(query)

    // ─────────────────────────────────────────────
    // LOAD DETAILS & SEASONS
    // ─────────────────────────────────────────────
    override suspend fun load(url: String): LoadResponse {
        // Expected url format: "https://cinestream.studio/watch/{movie|tv}/{tmdbId}"
        val uri = url.removePrefix("$mainUrl/watch/").split("/")
        val type = uri.getOrNull(0) ?: "movie"
        val tmdbId = uri.getOrNull(1) ?: throw ErrorLoadingException("Invalid CineStream ID")

        val apiUrl = "$mainUrl/api/$type/$tmdbId"
        val response = app.get(
            apiUrl,
            headers = mapOf(
                "User-Agent" to "Mozilla/5.0",
                "Referer" to "$mainUrl/"
            )
        ).text

        if (type == "tv") {
            val tv = tryParseJson<TmdbTvDetail>(response)
                ?: throw ErrorLoadingException("Failed to parse TV show details")

            val episodes = mutableListOf<Episode>()
            val totalSeasons = tv.numberOfSeasons ?: 1

            for (s in 1..totalSeasons) {
                val seasonUrl = "$mainUrl/api/tv/$tmdbId/season/$s"
                try {
                    val seasonRes = app.get(seasonUrl).text
                    val seasonJson = tryParseJson<TmdbSeasonDetail>(seasonRes)
                    seasonJson?.episodes?.forEach { ep ->
                        val epData = LinkData(
                            tmdbId = tmdbId.toInt(),
                            imdbId = tv.imdbId,
                            type = "tv",
                            season = s,
                            episode = ep.episodeNumber
                        )
                        episodes.add(
                            newEpisode(AppUtils.toJson(epData)) {
                                this.name = ep.name
                                this.season = s
                                this.episode = ep.episodeNumber
                                this.description = ep.overview
                                this.posterUrl = ep.stillPath?.let { "$TMDB_IMAGE_BASE$it" }
                                this.rating = (ep.voteAverage?.times(10))?.toInt()
                            }
                        )
                    }
                } catch (e: Exception) {
                    // Fallback to basic season representation
                    episodes.add(
                        newEpisode(
                            AppUtils.toJson(
                                LinkData(
                                    tmdbId = tmdbId.toInt(),
                                    imdbId = tv.imdbId,
                                    type = "tv",
                                    season = s,
                                    episode = 1
                                )
                            )
                        ) {
                            this.name = "Season $s Episode 1"
                            this.season = s
                            this.episode = 1
                        }
                    )
                }
            }

            return newTvSeriesLoadResponse(
                name = tv.name ?: tv.originalName ?: "Unknown",
                url = url,
                type = TvType.TvSeries,
                episodes = episodes
            ) {
                this.posterUrl = tv.posterPath?.let { "$TMDB_IMAGE_BASE$it" }
                this.backgroundPosterUrl = tv.backdropPath?.let { "$TMDB_BACKDROP_BASE$it" }
                this.plot = tv.overview
                this.year = tv.firstAirDate?.take(4)?.toIntOrNull()
                this.rating = (tv.voteAverage?.times(10))?.toInt()
                this.tags = tv.genres?.mapNotNull { it.name }
            }
        } else {
            val movie = tryParseJson<TmdbMovieDetail>(response)
                ?: throw ErrorLoadingException("Failed to parse movie details")

            val linkData = LinkData(
                tmdbId = tmdbId.toInt(),
                imdbId = movie.imdbId,
                type = "movie",
                season = null,
                episode = null
            )

            return newMovieLoadResponse(
                name = movie.title ?: movie.originalTitle ?: "Unknown",
                url = url,
                type = TvType.Movie,
                dataUrl = AppUtils.toJson(linkData)
            ) {
                this.posterUrl = movie.posterPath?.let { "$TMDB_IMAGE_BASE$it" }
                this.backgroundPosterUrl = movie.backdropPath?.let { "$TMDB_BACKDROP_BASE$it" }
                this.plot = movie.overview
                this.year = movie.releaseDate?.take(4)?.toIntOrNull()
                this.rating = (movie.voteAverage?.times(10))?.toInt()
                this.tags = movie.genres?.mapNotNull { it.name }
                this.duration = movie.runtime
            }
        }
    }

    // ─────────────────────────────────────────────
    // LOAD LINKS / VIDEO EXTRACTORS
    // ─────────────────────────────────────────────
    override suspend fun loadLinks(
        data: String,
        isCasting: Boolean,
        subtitleCallback: (SubtitleFile) -> Unit,
        callback: (ExtractorLink) -> Unit
    ): Boolean {
        val linkData = tryParseJson<LinkData>(data) ?: return false
        val id = linkData.tmdbId
        val type = linkData.type
        val s = linkData.season ?: 1
        val e = linkData.episode ?: 1

        // 1. Fetch Subtitles from CineStream Stremio / OpenSubtitles Integration
        
        try {
            val subUrl = if (type == "tv") {
                "$mainUrl/api/subtitles-stremio/series/${linkData.imdbId ?: id}:$s:$e"
            } else {
                "$mainUrl/api/subtitles-stremio/movie/${linkData.imdbId ?: id}"
            }
            val subRes = app.get(subUrl, timeout = 10).text
            val subJson = tryParseJson<SubtitleResponse>(subRes)
            subJson?.subtitles?.forEach { sub ->
                subtitleCallback(
                    SubtitleFile(
                        lang = sub.lang ?: "en",
                        url = sub.url ?: ""
                    )
                )
            }
        } catch (_: Exception) {}

        // 2. Direct CineStream Extractors & Embed Resolvers
        
        // Videasy 4K Direct Embed
        try {
            val videasyUrl = if (type == "tv") {
                "$VIDEASY_BASE/tv/$id/$s/$e"
            } else {
                "$VIDEASY_BASE/movie/$id"
            }
            loadExtractor(videasyUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // Vidy 4K Direct Stream
        try {
            val vidyUrl = if (type == "tv") {
                "$VIDY_BASE/tv/$id/$s/$e"
            } else {
                "$VIDY_BASE/movie/$id"
            }
            loadExtractor(vidyUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // VidBolt 1080p
        try {
            val vidboltUrl = if (type == "tv") {
                "$VIDBOLT_BASE/tv/$id/$s/$e"
            } else {
                "$VIDBOLT_BASE/movie/$id"
            }
            loadExtractor(vidboltUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // FilmU Multi-Server
        try {
            val filmuUrl = if (type == "tv") {
                "$FILMU_BASE/tv/$id/$s/$e?apikey=zyflix_premium_9x8c7v6b5n"
            } else {
                "$FILMU_BASE/movie/$id?apikey=zyflix_premium_9x8c7v6b5n"
            }
            loadExtractor(filmuUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // VidFast 4K
        try {
            val vidfastUrl = if (type == "tv") {
                "$VIDFAST_BASE/tv/$id/$s/$e"
            } else {
                "$VIDFAST_BASE/movie/$id"
            }
            loadExtractor(vidfastUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // Screenscape Stream
        try {
            val scUrl = if (type == "tv") {
                "$SCREENSCAPE_BASE?tmdb=$id&type=tv&s=$s&e=$e"
            } else {
                "$SCREENSCAPE_BASE?tmdb=$id&type=movie"
            }
            loadExtractor(scUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // VidSrc PM
        try {
            val vidsrcUrl = if (type == "tv") {
                "$VIDSRC_BASE/tv/$id/$s/$e"
            } else {
                "$VIDSRC_BASE/movie/$id"
            }
            loadExtractor(vidsrcUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        
        // Mapple Player
        try {
            val mappleUrl = if (type == "tv") {
                "$MAPPLE_BASE/tv/$id/$s/$e"
            } else {
                "$MAPPLE_BASE/movie/$id"
            }
            loadExtractor(mappleUrl, mainUrl, subtitleCallback, callback)
        } catch (_: Exception) {}

        return true
    }

    // ─────────────────────────────────────────────
    // HELPER EXTENSIONS & DATA CLASSES
    // ─────────────────────────────────────────────
    private fun TmdbItem.toSearchResponse(baseUrl: String): SearchResponse? {
        val tmdbId = id ?: return null
        val isTv = (mediaType == "tv") || (firstAirDate != null && title == null)
        val itemTitle = title ?: name ?: originalTitle ?: originalName ?: return null
        val poster = posterPath?.let { "$TMDB_IMAGE_BASE$it" }
        val releaseYear = (releaseDate ?: firstAirDate)?.take(4)?.toIntOrNull()
        val score = (voteAverage?.times(10))?.toInt()

        val watchUrl = "$baseUrl/watch/${if (isTv) "tv" else "movie"}/$tmdbId"

        return if (isTv) {
            newTvSeriesSearchResponse(itemTitle, watchUrl, TvType.TvSeries) {
                this.posterUrl = poster
                this.year = releaseYear
                this.rating = score
            }
        } else {
            newMovieSearchResponse(itemTitle, watchUrl, TvType.Movie) {
                this.posterUrl = poster
                this.year = releaseYear
                this.rating = score
            }
        }
    }

    private fun encodeUrl(str: String): String = java.net.URLEncoder.encode(str, "UTF-8")

